import { MessageSource, GetMessageEvent, GetPayload } from '../types';

export abstract class BaseMessageChannel<Outgoing, Incoming> {
    public abstract send<T extends keyof Outgoing>(type: T, payload: GetPayload<Outgoing, T>, origin?: string): void;

    public abstract makeRequest<T extends keyof Outgoing, RT extends keyof Incoming>(type: T, payload: GetPayload<Outgoing, T>, responseType: RT, source: MessageSource): Promise<GetPayload<Outgoing, T>>;

    public abstract waitForResponse<T extends keyof Incoming>(type: T, source: MessageSource): Promise<GetPayload<Incoming, T>>;

    protected abstract onMessage<T extends keyof Incoming>(event: GetMessageEvent<Incoming, T>): void
}
